private List<ProductMenuTreeDTO> getChildrensConfiguredMenu(
        List<ProductMenu> all, Long parentId, String category) {
    List<ProductMenuTreeDTO> result = new ArrayList<>();
    for (ProductMenu menu : all) {
        if (!Objects.equals(menu.getProductMenuId(), parentId)) {
            continue;
        }
        ProductMenuTreeDTO node = new ProductMenuTreeDTO();
        node.setId(menu.getId());
        node.setMenuName(menu.getMenuName());
        // 端标识不落库到子节点，由根的 category 逐层传下来
        node.setCategory(category);
        node.setFavorite(menu.getFavorite());
        node.setFavoriteSort(menu.getFavoriteSort());
        node.setChildList(getChildrensConfiguredMenu(all, menu.getId(), category));
        result.add(node);
    }
    return result;
}

