private boolean isKeepComponentMenu(ComponentMenu menu, String targetEnd) {
    String menuGroup = StringUtils.defaultString(menu.getMenuGroup(), MENU_GROUP_WEB);
    if (CATEGORY_H5.equals(targetEnd)) {
        // H5 端只保留 h5 菜单
        return MENU_GROUP_H5.equals(menuGroup);
    }
    // web 端保留 web 菜单；h5 菜单不在 web 端出现
    return MENU_GROUP_WEB.equals(menuGroup);
}
